std::mt19937 urng; // Uniform Random Number Generator (Engine state)

// Distribution definition (State holds distribution parameters)
std::uniform_real_distribution<> dist(0.0, 1.0);

// Invocation: dist.operator()(urng)
// Advances urng state and applies transformation function
double random_num = dist(urng);

// Example using auto for concise parameter binding
auto roll_dice = std::uniform_int_distribution<>(1, 6);
int result = roll_dice(urng);

// Poisson distribution example
std::poisson_distribution<> pd(2.5);
int count = pd(urng);
